Item.method_code:
	BusinessLogic businessLogic = new BusinessLogic(this, RequestState, CCO.ErrorLookup);
	businessLogic.Run();

	return this;
}

private sealed class BusinessLogic
{
	private readonly Aras.Server.Core.IContextState requestState;
	private readonly Aras.Server.Core.Abstractions.IErrorLookup errorLookup;
	private readonly Item contextItems;

	public BusinessLogic(Item contextItems, Aras.Server.Core.IContextState requestState, Aras.Server.Core.Abstractions.IErrorLookup errorLookup)
	{
		this.errorLookup = errorLookup;
		this.requestState = requestState;
		this.contextItems = contextItems;
	}

	public void Run()
	{
		if (requestState.Contains("expiration_status_requested") &&
			((bool)requestState["expiration_status_requested"]))
		{
			int itemsCount = this.contextItems.getItemCount();
			for (int i = 0; i < itemsCount; i++)
			{
				Item contextItem = this.contextItems.getItemByIndex(i);

				string messageExpired = this.errorLookup.Lookup("FeatureLicenseStatusExpired");
				string messageNotExpired = this.errorLookup.Lookup("FeatureLicenseStatusActive");
				string expirationDateString = contextItem.getProperty("expiration_date");
				string mlStatus = messageNotExpired;
				string status = "active";

				if (!string.IsNullOrEmpty(expirationDateString) && IsLicenseExpired(expirationDateString))
				{
					mlStatus = messageExpired;
					status = "expired";
				}

				string startDateString = contextItem.getProperty("start_date");
				if (!string.IsNullOrEmpty(startDateString) &&
					DateTime.TryParse(startDateString, CultureInfo.InvariantCulture, out DateTime startDate) &&
					startDate.Date > DateTime.UtcNow.Date)
				{
					mlStatus = this.errorLookup.Lookup("FeatureLicenseStatusUpcoming");
					status = "upcoming";
				}

				contextItem.setProperty("expiration_status", mlStatus);
				contextItem.setProperty("expiration_status_mark", status);
			}
		}
	}

	private static bool IsLicenseExpired(string expirationDateString)
	{
		if (!DateTime.TryParse(expirationDateString, CultureInfo.InvariantCulture, out DateTime expirationDate))
		{
			return true;
		}

		return expirationDate.Date < DateTime.UtcNow.Date;
	}
